95	func (f *fakeEchoAPI) waitStarted(t *testing.T, n int) {
96		t.Helper()
97		for i := 0; i < n; i++ {
98			select {
99			case <-f.started:
100			case <-time.After(2 * time.Second):
101				t.Fatalf("echo call %d of %d never started", i+1, n)
102			}
103		}
104	}
105	
106	// waitFor polls cond up to 2 s; it only bounds a wait, it never replaces a sync.
107	func waitFor(t *testing.T, what string, cond func() bool) {
108		t.Helper()
109		deadline := time.Now().Add(2 * time.Second)
110		for !cond() {
111			if time.Now().After(deadline) {
112				t.Fatalf("timed out waiting for %s", what)
113			}
114			time.Sleep(time.Millisecond)
115		}
116	}
